import { build } from 'vite';
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
const sources = ['contract.ts', 'handler.ts', 'index.ts'];
const hashes = await Promise.all(
  sources.map(
    async (name) =>
      name +
      ' sha256=' +
      createHash('sha256')
        .update(await readFile('supabase/functions/material-analyze/' + name))
        .digest('hex'),
  ),
);
const result = await build({
  configFile: false,
  logLevel: 'silent',
  build: {
    target: 'es2022',
    write: false,
    minify: false,
    lib: {
      entry: 'supabase/functions/material-analyze/index.ts',
      formats: ['es'],
      fileName: () => 'index.js',
    },
    rolldownOptions: { external: (id) => id.startsWith('npm:') },
  },
});
const outputs = Array.isArray(result) ? result : [result];
const chunks = outputs.flatMap((output) => output.output).filter((file) => file.type === 'chunk');
if (chunks.length !== 1) throw Error('Editor deployment must be exactly one JavaScript module.');
const content =
  '// GENERATED by npm run edge:generate. DO NOT EDIT.\n// Canonical files: supabase/functions/material-analyze/.\n// ' +
  hashes.join('\n// ') +
  '\n' +
  chunks[0].code;
const path = 'supabase/StudyHub_material_analyze.js';
if (process.argv.includes('--check')) {
  if ((await readFile(path, 'utf8').catch(() => null)) !== content)
    throw Error('Stale editor bundle. Run npm run edge:generate.');
  console.log('Editor deployment bundle matches canonical sources.');
} else {
  await writeFile(path, content);
  console.log('Generated single-file editor deployment: ' + path);
}
